gxV(){return"\u092f\u0939 \u0915\u0938\u094d\u091f\u092e \u092b\u093c\u0940\u0932\u094d\u0921 \u0915\u093e\u0930\u094d\u092f\u094b\u0902 \u092a\u0930 \u0932\u093e\u0917\u0942 \u0939\u094b\u0924\u0940 \u0939\u0948 \u092f\u093e \u0938\u0902\u0938\u093e\u0927\u0928\u094b\u0902 \u092a\u0930\u0964"},
gxU(){return"\u0915\u0938\u094d\u091f\u092e \u092b\u093c\u0940\u0932\u094d\u0921 \u0915\u093e\u0930\u094d\u092f \u0926\u0943\u0936\u094d\u092f\u094b\u0902 \u092e\u0947\u0902 \u090f\u0915 \u0915\u0949\u0932\u092e \u0915\u0947 \u0930\u0942\u092a \u092e\u0947\u0902 \u0926\u093f\u0916\u093e\u0908 \u0926\u0947\u0917\u0940 \u0914\u0930 \u0935\u094d\u092f\u0915\u094d\u0924\u093f\u0917\u0924 \u0915\u093e\u0930\u094d\u092f\u094b\u0902 \u0915\u094b \u0905\u0938\u093e\u0907\u0928 \u0915\u0940 \u091c\u093e \u0938\u0915\u0924\u0940 \u0939\u0948\u0964"},
gxT(){return"\u0915\u0938\u094d\u091f\u092e \u092b\u093c\u0940\u0932\u094d\u0921 \u0938\u0902\u0938\u093e\u0927\u0928 \u0926\u0943\u0936\u094d\u092f\u094b\u0902 \u092e\u0947\u0902 \u090f\u0915 \u0915\u0949\u0932\u092e \u0915\u0947 \u0930\u0942\u092a \u092e\u0947\u0902 \u0926\u093f\u0916\u093e\u0908 \u0926\u0947\u0917\u0940 \u0914\u0930 \u0935\u094d\u092f\u0915\u094d\u0924\u093f\u0917\u0924 \u0938\u0902\u0938\u093e\u0927\u0928\u094b\u0902 \u0915\u094b \u0905\u0938\u093e\u0907\u0928 \u0915\u0940 \u091c\u093e \u0938\u0915\u0924\u0940 \u0939\u0948\u0964"},
gy3(){return"\u0907\u0938 \u0915\u0938\u094d\u091f\u092e \u092b\u093c\u0940\u0932\u094d\u0921 \u0915\u0947 \u0932\u093f\u090f \u0921\u0947\u091f\u093e \u092a\u094d\u0930\u0915\u093e\u0930, \u091c\u094b \u092f\u0939 \u0928\u093f\u0930\u094d\u0927\u093e\u0930\u093f\u0924 \u0915\u0930\u0924\u093e \u0939\u0948 \u0915\u093f \u092e\u093e\u0928 \u0915\u0948\u0938\u0947 \u0926\u0930\u094d\u091c \u0914\u0930 \u092a\u094d\u0930\u0926\u0930\u094d\u0936\u093f\u0924 \u0915\u093f\u090f \u091c\u093e\u0924\u0947 \u0939\u0948\u0902\u0964"},
gpZ(){return"\u092e\u093e\u0928 \u0938\u0902\u0917\u094d\u0930\u0939\u0940\u0924 \u0915\u0930\u0928\u0947 \u0915\u0947 \u0932\u093f\u090f \u0909\u092a\u092f\u094b\u0917 \u0915\u093f\u092f\u093e \u091c\u093e\u0928\u0947 \u0935\u093e\u0932\u093e \u0906\u0902\u0924\u0930\u093f\u0915 \u092b\u093c\u0940\u0932\u094d\u0921 \u0938\u094d\u0932\u0949\u091f\u0964 \u092a\u094d\u0930\u0924\u094d\u092f\u0947\u0915 \u0938\u094d\u0932\u0949\u091f (\u0909\u0926\u093e., Text1, Number3) \u0915\u0947\u0935\u0932 \u090f\u0915 \u0915\u0938\u094d\u091f\u092e \u092b\u093c\u0940\u0932\u094d\u0921 \u0926\u094d\u0935\u093e\u0930\u093e \u0909\u092a\u092f\u094b\u0917 \u0915\u093f\u092f\u093e \u091c\u093e \u0938\u0915\u0924\u093e \u0939\u0948\u0964"},
gxO(){return"\u0906\u0902\u0924\u0930\u093f\u0915 \u092b\u093c\u0940\u0932\u094d\u0921 \u0928\u093e\u092e \u0915\u0947 \u0938\u094d\u0925\u093e\u0928 \u092a\u0930 \u0926\u093f\u0916\u093e\u092f\u093e \u091c\u093e\u0928\u0947 \u0935\u093e\u0932\u093e \u0909\u092a\u092f\u094b\u0917\u0915\u0930\u094d\u0924\u093e-\u0905\u0928\u0941\u0915\u0942\u0932 \u0928\u093e\u092e (\u0909\u0926\u093e., 'Text1' \u0915\u0947 \u092c\u091c\u093e\u092f '\u092a\u094d\u0930\u094b\u091c\u0947\u0915\u094d\u091f \u0915\u094b\u0921')\u0964"},
gxX(){return"\u092a\u0942\u0930\u094d\u0935\u0928\u093f\u0930\u094d\u0927\u093e\u0930\u093f\u0924 \u092e\u093e\u0928\u094b\u0902 \u0915\u0940 \u0938\u0942\u091a\u0940 \u091c\u093f\u0928\u092e\u0947\u0902 \u0938\u0947 \u0909\u092a\u092f\u094b\u0917\u0915\u0930\u094d\u0924\u093e \u0915\u093f\u0938\u0940 \u0915\u093e\u0930\u094d\u092f \u092a\u0930 \u092f\u0939 \u092b\u093c\u0940\u0932\u094d\u0921 \u0938\u0947\u091f \u0915\u0930\u0924\u0947 \u0938\u092e\u092f \u091a\u0941\u0928 \u0938\u0915\u0924\u0947 \u0939\u0948\u0902\u0964"},
gy_(){return"\u091a\u0947\u0915 \u0939\u094b\u0928\u0947 \u092a\u0930, \u0915\u0947\u0935\u0932 \u0932\u0941\u0915\u0905\u092a \u0924\u093e\u0932\u093f\u0915\u093e \u0915\u0947 \u092e\u093e\u0928 \u0905\u0938\u093e\u0907\u0928 \u0915\u093f\u090f \u091c\u093e \u0938\u0915\u0924\u0947 \u0939\u0948\u0902\u0964 \u092b\u093c\u0940\u0932\u094d\u0921 \u092b\u094d\u0930\u0940-\u092b\u093c\u0949\u0930\u094d\u092e \u0907\u0928\u092a\u0941\u091f \u0915\u0947 \u092c\u091c\u093e\u092f \u0921\u094d\u0930\u0949\u092a\u0921\u093e\u0909\u0928 \u092c\u0928 \u091c\u093e\u0924\u0940 \u0939\u0948\u0964"},
gxQ(){return"\u091a\u0947\u0915 \u0939\u094b\u0928\u0947 \u092a\u0930, \u0909\u092a\u092f\u094b\u0917\u0915\u0930\u094d\u0924\u093e \u0932\u0941\u0915\u0905\u092a \u0924\u093e\u0932\u093f\u0915\u093e \u092e\u0947\u0902 \u0928\u0939\u0940\u0902 \u092e\u094c\u091c\u0942\u0926 \u092e\u093e\u0928 \u0926\u0930\u094d\u091c \u0915\u0930 \u0938\u0915\u0924\u0947 \u0939\u0948\u0902, \u0914\u0930 \u0935\u0947 \u092e\u093e\u0928 \u0938\u094d\u0935\u091a\u093e\u0932\u093f\u0924 \u0930\u0942\u092a \u0938\u0947 \u0938\u0942\u091a\u0940 \u092e\u0947\u0902 \u091c\u094b\u0921\u093c \u0926\u093f\u090f \u091c\u093e\u0924\u0947 \u0939\u0948\u0902\u0964"},
gAP(){return"\u0915\u0938\u094d\u091f\u092e \u092b\u093c\u0940\u0932\u094d\u0921"},
gFG(){return"\u0932\u093e\u0917\u0924"},
gFC(){return"\u0932\u093e\u0917\u0924 \u0926\u0930 \u0924\u093e\u0932\u093f\u0915\u093e:"},
gFD(){return"\u0907\u0938 \u0905\u0938\u093e\u0907\u0928\u092e\u0947\u0902\u091f \u0915\u0947 \u0932\u093f\u090f \u0932\u093e\u0917\u0924 \u0917\u0923\u0928\u093e \u092e\u0947\u0902 \u0909\u092a\u092f\u094b\u0917 \u0915\u0940 \u091c\u093e\u0928\u0947 \u0935\u093e\u0932\u0940 \u0926\u0930 \u0924\u093e\u0932\u093f\u0915\u093e (A\u2013E)\u0964 \u092a\u094d\u0930\u0924\u094d\u092f\u0947\u0915 \u0924\u093e\u0932\u093f\u0915\u093e \u092e\u0947\u0902 \u0905\u0932\u0917-\u0905\u0932\u0917 \u092e\u093e\u0928\u0915 \u0914\u0930 \u0913\u0935\u0930\u091f\u093e\u0907\u092e \u0926\u0930\u0947\u0902 \u0939\u094b \u0938\u0915\u0924\u0940 \u0939\u0948\u0902\u0964"},
gxI(){return"\u092a\u094d\u0930\u0924\u093f \u0909\u092a\u092f\u094b\u0917 \u0932\u093e\u0917\u0924:"},
gxJ(){return"\u0939\u0930 \u092c\u093e\u0930 \u091c\u092c \u092f\u0939 \u0938\u0902\u0938\u093e\u0927\u0928 \u0915\u093f\u0938\u0940 \u0915\u093e\u0930\u094d\u092f \u0915\u094b \u0905\u0938\u093e\u0907\u0928 \u0915\u093f\u092f\u093e \u091c\u093e\u0924\u093e \u0939\u0948 \u0924\u094b \u090f\u0915 \u0928\u093f\u0936\u094d\u091a\u093f\u0924 \u0932\u093e\u0917\u0924 \u091a\u093e\u0930\u094d\u091c \u0915\u0940 \u091c\u093e\u0924\u0940 \u0939\u0948\u0964"},
gEZ(){return"\u0926\u0930 \u0924\u093e\u0932\u093f\u0915\u093e:"},
gF_(){return"\u0926\u0930 \u0924\u093e\u0932\u093f\u0915\u093e\u090f\u0901 (A\u2013E) \u0906\u092a\u0915\u094b \u090f\u0915 \u0939\u0940 \u0938\u0902\u0938\u093e\u0927\u0928 \u0915\u0947 \u0932\u093f\u090f \u0905\u0932\u0917-\u0905\u0932\u0917 \u0932\u093e\u0917\u0924 \u0926\u0930\u0947\u0902 \u092a\u0930\u093f\u092d\u093e\u0937\u093f\u0924 \u0915\u0930\u0928\u0947 \u0926\u0947\u0924\u0940 \u0939\u0948\u0902\u0964 \u092a\u094d\u0930\u0924\u094d\u092f\u0947\u0915 \u0905\u0938\u093e\u0907\u0928\u092e\u0947\u0902\u091f \u090f\u0915 \u0905\u0932\u0917 \u0924\u093e\u0932\u093f\u0915\u093e \u0915\u093e \u0909\u092a\u092f\u094b\u0917 \u0915\u0930 \u0938\u0915\u0924\u093e \u0939\u0948, \u0909\u0926\u093e\u0939\u0930\u0923 \u0915\u0947 \u0932\u093f\u090f \u092a\u0930\u093e\u092e\u0930\u094d\u0936 \u0915\u0947 \u0932\u093f\u090f \u090f\u0915 \u0926\u0930 \u0914\u0930 \u092a\u094d\u0930\u0936\u093f\u0915\u094d\u0937\u0923 \u0915\u0947 \u0932\u093f\u090f \u0926\u0942\u0938\u0930\u0940\u0964"},
grm(){return"A (\u0921\u093f\u092b\u093c\u0949\u0932\u094d\u091f)"},
grn(){return"B"},
gro(){return"C"},
