grq(){return"E"},
gvW(){return"\u0926\u0930 \u091c\u094b\u0921\u093c\u0947\u0902"},
gqh(){return"\u092a\u094d\u0930\u092d\u093e\u0935\u0940 \u0924\u093f\u0925\u093f:"},
gyY(){return"\u0935\u0939 \u0924\u093f\u0925\u093f \u091c\u093f\u0938\u0938\u0947 \u092f\u0939 \u0926\u0930 \u0932\u093e\u0917\u0942 \u0939\u094b\u0924\u0940 \u0939\u0948\u0964"},
gwl(){return"\u2014"},
gwm(){return"\u0906\u0927\u093e\u0930 \u0926\u0930 \u092a\u094d\u0930\u094b\u091c\u0947\u0915\u094d\u091f \u092a\u094d\u0930\u093e\u0930\u0902\u092d \u0938\u0947 \u0932\u093e\u0917\u0942 \u0939\u094b\u0924\u0940 \u0939\u0948\u0964 \u092c\u093e\u0926 \u0915\u0940 \u0924\u093f\u0925\u093f \u092a\u0930 \u0926\u0930 \u092c\u0926\u0932\u0928\u0947 \u0915\u0947 \u0932\u093f\u090f \u0928\u0940\u091a\u0947 \u092a\u0902\u0915\u094d\u0924\u093f\u092f\u093e\u0901 \u091c\u094b\u0921\u093c\u0947\u0902\u0964"},
gFt(){return"\u0909\u092a\u0932\u092c\u094d\u0927\u0924\u093e"},
gFr(){return"\u0938\u0902\u0938\u093e\u0927\u0928 \u0909\u092a\u0932\u092c\u094d\u0927\u0924\u093e"},
gFs(){return"\u0938\u092e\u092f \u0905\u0935\u0927\u093f \u092a\u0930\u093f\u092d\u093e\u0937\u093f\u0924 \u0915\u0930\u0947\u0902 \u091c\u092c \u0938\u0902\u0938\u093e\u0927\u0928 \u0915\u0940 \u0905\u0932\u0917 \u0909\u092a\u0932\u092c\u094d\u0927\u0924\u093e (\u0907\u0915\u093e\u0907\u092f\u093e\u0901) \u0939\u094b\u0964 \u0907\u0928 \u0905\u0935\u0927\u093f\u092f\u094b\u0902 \u0915\u0947 \u092c\u093e\u0939\u0930, \u0921\u093f\u092b\u093c\u0949\u0932\u094d\u091f \u0905\u0927\u093f\u0915\u0924\u092e \u0907\u0915\u093e\u0908 \u092e\u093e\u0928 \u0932\u093e\u0917\u0942 \u0939\u094b\u0924\u093e \u0939\u0948\u0964"},
gwi(){return"\u0909\u092a\u0932\u092c\u094d\u0927 \u0924\u093f\u0925\u093f \u0938\u0947:"},
gwj(){return"\u0909\u092a\u0932\u092c\u094d\u0927 \u0924\u093f\u0925\u093f \u0924\u0915:"},
